questions.tests:
def ev(direction, scope):
    return {"direction": direction, "scope": scope}

# the four cells of section 1
assert annotate([ev("into", "one")]) == ["S"]
assert annotate([ev("out", "one")]) == ["C"]
assert annotate([ev("into", "several")]) == ["I"], annotate([ev("into", "several")])
assert annotate([ev("out", "several")]) == ["W"], annotate([ev("out", "several")])
# the walk-through of section 9: three writes at setup, four selects, two compresses, a write, an isolate, a write
session = ([ev("out", "several")] * 3 + [ev("into", "one")] * 4 + [ev("out", "one")] * 2
           + [ev("out", "several"), ev("into", "several"), ev("out", "several")])
letters = annotate(session)
assert "".join(letters) == "WWWSSSSCCWIW", letters
assert {k: letters.count(k) for k in "WSCI"} == {"W": 5, "S": 4, "C": 2, "I": 1}
assert annotate([]) == []
# every event lands in exactly one cell: anything else is refused
for bad in (ev("sideways", "one"), ev("into", "many"), ev("Out", "one")):
    try:
        annotate([bad])
    except ValueError:
        pass
    else:
        raise AssertionError(f"accepted {bad}")
print("all tests passed")
